describe('Search Results Sorting', () => {
    beforeEach(() => {
        cy.visit('/search'); // Adjust the URL as necessary
    });

    it('should sort search results by relevance', () => {
        cy.get('select#sort-options').select('Relevance');
        cy.get('.search-result').first().should('contain', 'Expected Result for Relevance');
    });

    it('should sort search results by price', () => {
        cy.get('select#sort-options').select('Price');
        cy.get('.search-result').first().should('contain', 'Expected Result for Price');
    });

    it('should handle no results found when sorting', () => {
        cy.get('select#sort-options').select('Date');
        cy.get('.search-result').should('have.length', 0);
        cy.get('.no-results-message').should('be.visible').and('contain', 'No results found');
    });
});
